"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97663"],{74286(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.remanejamento_destino_obrigatorio","status":422,"titulo":"Modalidade com remanejamento DESTINO_UNICO exige o destino"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.remanejamento_destino_obrigatorio","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada declarou `regraRemanejamento: DESTINO_UNICO` sem\\ndeclarar `remanejamentoDestino`. Ao contr\xe1rio da cascata legal (obrigat\xf3ria\\npara cota reservada, ver\\n[`cota_reservada_exige_cascata`](/erros/uniplus.selecao.modalidade_selecionada.cota_reservada_exige_cascata)),\\n`DESTINO_UNICO` \xe9 um remanejamento simples, de uma modalidade para uma \xfanica\\noutra \u2014 mas precisa dizer qual; sem o destino, as vagas ociosas n\xe3o t\xeam para\\nonde ir.","Regra de remanejamento (`DESTINO_UNICO`, `CRUZADO`, `SEGUE_ORDEM_DE_REMANEJAMENTO` \u2014 o\\nvocabul\xe1rio inteiro) \xe9 independente da composi\xe7\xe3o de vagas (`RETIRADA_DE_OUTRA_MODALIDADE`, ver\\n[`composicao_origem_obrigatoria`](/erros/uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria))\\n\u2014 a primeira decide o destino das vagas ociosas da modalidade; a segunda,\\ncomo ela entra no c\xe1lculo do quadro. Esta recusa sai junto com as demais recusas da modalidade; corrija todas antes de selecionar de novo.","**`regraRemanejamento` e `remanejamentoDestino` n\xe3o v\xeam do corpo do pedido da\\ndefini\xe7\xe3o de distribui\xe7\xe3o de vagas** \u2014 s\xe3o copiados do cadastro de\\nmodalidades de Configura\xe7\xe3o, no momento em que a modalidade \xe9 selecionada.\\nO pr\xf3prio cadastro j\xe1 impede esta incoer\xeancia na\\nescrita, tanto na cria\xe7\xe3o quanto na atualiza\xe7\xe3o; pela defini\xe7\xe3o de\\ndistribui\xe7\xe3o de vagas, este c\xf3digo s\xf3 aparece se a modalidade estiver\\ngravada no cadastro de um jeito que contorna essa valida\xe7\xe3o.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma cria\xe7\xe3o \xe9 conferida de novo.","Enquanto houver a recusa de [cota reservada fora da ordem legal](/erros/uniplus.selecao.modalidade_selecionada.cota_reservada_exige_cascata), os par\xe2metros do remanejamento n\xe3o s\xe3o conferidos. Corrija primeiro a cota para que essa confer\xeancia aconte\xe7a."],"comoResolver":["O campo que falta n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade\\ncadastrada em Configura\xe7\xe3o. Corrija l\xe1 o v\xednculo entre `remanejamento.regra:\\nDESTINO_UNICO` e o destino, ou investigue como a modalidade foi gravada sem\\nessa coer\xeancia.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema tamb\xe9m n\xe3o est\xe1\\nno que foi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada, que reflete\\numa modalidade j\xe1 incoerente no momento em que foi selecionada."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);